let current = 'en';

export function t(key) { return copy[current]?.[key] || copy.en[key] || key; }
export function format(key, values = {}) { return Object.entries(values).reduce((value, [name, replacement]) => value.replaceAll(`{${name}}`, replacement), t(key)); }
export function currentLanguage() { return current; }
export function missingTranslationKeys() {
  const required = Object.keys(copy.en);
  return Object.fromEntries(Object.entries(copy).map(([language, values]) => [language, required.filter((key) => values[key] === undefined || values[key] === '')]));
}

export function setLanguage(language) {
  current = copy[language] ? language : 'en';
  document.documentElement.lang = current;
  document.querySelectorAll('[data-i18n]').forEach((element) => {
    const translated = t(element.dataset.i18n);
    if (element.tagName === 'OPTION') element.textContent = translated.replace(/<[^>]*>/g, '');
    else element.innerHTML = translated;
  });
  document.querySelectorAll('[data-i18n-aria-label]').forEach((element) => { element.setAttribute('aria-label', t(element.dataset.i18nAriaLabel)); });
  document.querySelectorAll('[data-i18n-placeholder]').forEach((element) => { element.setAttribute('placeholder', t(element.dataset.i18nPlaceholder)); });
  localStorage.setItem('nearsignal-language', current);
  document.dispatchEvent(new CustomEvent('nearsignal:language', { detail: current }));
}

export function initLanguage() {
  const select = document.getElementById('languageSelect');
  const saved = localStorage.getItem('nearsignal-language') || localStorage.getItem('careroute-language');
  const preferred = copy[saved] ? saved : (copy[navigator.language?.slice(0, 2)] ? navigator.language.slice(0, 2) : 'en');
  select.value = preferred;
  select.addEventListener('change', () => setLanguage(select.value));
  setLanguage(preferred);
}
